@Timeout(60)
class LmdbBackupHeadAuthorityTest {

	@Test
	void acknowledgedHeadSurvivesMaintenanceRollbackRestartAndRestore(@TempDir Path directory) throws Exception {
		Path live = directory.resolve("live");
		Path backups = directory.resolve("backups");
		long retained;
		UUID identity;
		byte[] header;
		LmdbStore store = open(live);
		try {
			BackupResult baseline = full(store, backups);
			add(store, "retained");
			retained = incremental(store, backups, baseline.getEndTransactionId()).getEndTransactionId();
			awaitAcknowledgement(store, retained);
			TripleStore triples = store.getBackingStore().getTripleStore();
			identity = triples.getBackupOutboxHead();
			header = triples.readBackupStageHeader(retained);
			assertEquals(List.of(retained), triples.listBackupStageTransactions(0, Long.MAX_VALUE));

			// The same no-stage metadata commit is used during store maintenance/initialization. Make it a
			// real native write, without introducing a logical backup successor that could replace the head.
			Map<String, String> metadata = Map.of("maintenance", "urn:maintenance:");
			triples.commitNamespaceSnapshot(metadata, triples.prepareReplayDecision(), false);
			assertEquals(metadata, triples.readNamespaceSnapshot());
			assertEquals(retained, triples.getRequiredBackupTxnId());
			assertEquals(identity, triples.getBackupOutboxHead());
			assertArrayEquals(header, triples.readBackupStageHeader(retained),
					"An acknowledged latest header is still authoritative after a no-stage physical commit");
		} finally {
			store.shutDown();
		}

		store = open(live);
		try {
			TripleStore triples = store.getBackingStore().getTripleStore();
			assertEquals(retained, triples.getRequiredBackupTxnId());
			assertEquals(identity, triples.getBackupOutboxHead());
			triples.beforePhysicalCommitForTest = () -> {
				throw new SailException("Abort replacement after native staging and reclamation");
			};
			LmdbStore aborting = store;
			assertThrows(SailException.class, () -> add(aborting, "aborted"));
			triples.beforePhysicalCommitForTest = null;
			assertEquals(retained, triples.getRequiredBackupTxnId());
			assertEquals(identity, triples.getBackupOutboxHead());
			assertEquals(List.of(retained), triples.listBackupStageTransactions(0, Long.MAX_VALUE));
			assertArrayEquals(header, triples.readBackupStageHeader(retained),
					"Rollback must restore a retained header reclaimed by the aborted replacement");
		} finally {
			store.getBackingStore().getTripleStore().beforePhysicalCommitForTest = null;
			store.shutDown();
		}

		store = open(live);
		try {
			assertEquals(retained, store.getBackingStore().getCurrentCommittedTxnId());
			assertEquals(identity, store.getBackingStore().getTripleStore().getBackupOutboxHead());
			BackupResult retainedFull = full(store, backups);
			add(store, "replacement");
			BackupResult delta = incremental(store, backups, retainedFull.getEndTransactionId());
			assertEquals(retained + 1, delta.getEndTransactionId());
			Path exported = directory.resolve("exported");
			List<Path> logs = ((LmdbBackupServiceImpl) store.getBackupService())
					.exportTransactionLogs(backups, retained, delta.getEndTransactionId(), exported);
			assertEquals(1, logs.size());
			try (var input = new GZIPInputStream(java.nio.file.Files.newInputStream(logs.getFirst()))) {
				var journal = LmdbBackupDeltaCodec.readJournal(input);
				assertEquals(retained, journal.previousTransactionId());
				assertEquals(1, journal.records().size());
				assertEquals("urn:authority:replacement",
						journal.records().getFirst().getStatement().getSubject().stringValue());
			}

			// The full copied the retained native header; replay advances the restored namespace boundary beyond it.
			Path restored = store.getBackupService()
					.restore(new PointInTimeRestoreRequest(backups,
							directory.resolve("restored"), delta.getEndTransactionId(), true));
			LmdbStore copy = open(restored);
			try {
				assertEquals(delta.getEndTransactionId(), copy.getBackingStore().getCurrentCommittedTxnId());
				assertContents(copy, 2);
				Path nextBackups = directory.resolve("restored-backups");
				// Restoring starts a new journal generation, whose first full snapshot establishes its baseline.
				BackupResult nextFull = full(copy, nextBackups);
				add(copy, "after-restore");
				BackupResult nextDelta = incremental(copy, nextBackups, nextFull.getEndTransactionId());
				assertEquals(delta.getEndTransactionId() + 1, nextDelta.getEndTransactionId());
				Path twice = copy.getBackupService()
						.restore(new PointInTimeRestoreRequest(nextBackups,
								directory.resolve("restored-twice"), nextDelta.getEndTransactionId(), true));
				LmdbStore twiceRestored = open(twice);
				try {
					assertContents(twiceRestored, 3);
				} finally {
					twiceRestored.shutDown();
				}
			} finally {
				copy.shutDown();
			}
		} finally {
			store.shutDown();
		}
	}

	private static void awaitAcknowledgement(LmdbStore store, long transaction) {
		PostCommitBackupPublisher publisher = store.getBackingStore().backupPublisher();
		long deadline = System.nanoTime() + TimeUnit.SECONDS.toNanos(10);
		while (publisher.acknowledgedTransactionId() < transaction && System.nanoTime() < deadline) {
			Thread.yield();
		}
		assertTrue(publisher.acknowledgedTransactionId() >= transaction);
	}

	private static LmdbStore open(Path directory) {
		LmdbStore store = new LmdbStore(directory.toFile(),
				new LmdbStoreConfig("spoc,posc").setBackupJournalEnabled(true));
		store.init();
		return store;
	}

	private static BackupResult full(LmdbStore store, Path backups) {
		return store.getBackupService().createBackup(BackupRequest.builder(backups, BackupType.FULL).build());
	}

	private static BackupResult incremental(LmdbStore store, Path backups, long since) {
		return store.getBackupService()
				.createBackup(BackupRequest.builder(backups, BackupType.INCREMENTAL)
						.sinceTransactionId(since)
						.build());
	}

	private static void add(LmdbStore store, String name) {
		var vf = SimpleValueFactory.getInstance();
		try (var connection = store.getConnection()) {
			connection.begin();
			connection.addStatement(vf.createIRI("urn:authority:" + name), vf.createIRI("urn:authority:p"),
					vf.createLiteral(name));
			connection.commit();
		}
	}

	private static void assertContents(LmdbStore store, long size) {
		try (var connection = store.getConnection()) {
			assertEquals(size, connection.size());
			assertFalse(connection.hasStatement(SimpleValueFactory.getInstance().createIRI("urn:authority:aborted"),
					null, null, false));
			assertEquals("urn:maintenance:", connection.getNamespace("maintenance"));
		}
	}
}
